import{_ as o,o as t,c as s,a3 as a}from"./chunks/framework.DH50UWNB.js";const p=JSON.parse('{"title":"Evidence storage","description":"Where Wake keeps evidence files such as screenshots and logs: the bundled MinIO, how presigned uploads move files, and using your own storage.","frontmatter":{"description":"Where Wake keeps evidence files such as screenshots and logs: the bundled MinIO, how presigned uploads move files, and using your own storage."},"headers":[],"relativePath":"run/evidence-storage.md","filePath":"run/evidence-storage.md","lastUpdated":1794486787000}'),r={name:"run/evidence-storage.md"};function d(n,e,i,c,l,h){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="evidence-storage" tabindex="-1">Evidence storage <a class="header-anchor" href="#evidence-storage" aria-label="Permalink to &quot;Evidence storage&quot;">​</a></h1><p>Evidence files, such as the screenshots and logs your agents attach to tasks, live in S3-compatible storage, never in the database. An installation runs MinIO for them, with the bucket and a storage user already set up. In local mode it listens on the evidence address the installer set up (see <a href="/wake-dist/docs/run/install-options#options">Install options</a>); on a domain, on <code>https://s3.&lt;your domain&gt;</code>. The server uses a storage user limited to that bucket; see <a href="/wake-dist/docs/run/install-options#hardened-services">Hardened services</a>.</p><h2 id="how-files-move" tabindex="-1">How files move <a class="header-anchor" href="#how-files-move" aria-label="Permalink to &quot;How files move&quot;">​</a></h2><p>Files never pass through the server:</p><ul><li>Agents upload with a presigned <code>PUT</code> valid for 10 minutes, straight to the storage (<code>wake evidence</code>, or Wake&#39;s MCP tools).</li><li>The web app downloads through a redirect to a presigned <code>GET</code> valid for 5 minutes.</li><li>A file is at most 10 MiB. Screenshots are <code>.png</code>, <code>.jpg</code>, <code>.jpeg</code>, <code>.webp</code> or <code>.gif</code>; text is <code>.txt</code> or <code>.log</code>.</li></ul><p>So the storage&#39;s address must be reachable by your agents for uploads and by browsers for downloads. It serves only the evidence bucket: every other path there, MinIO&#39;s admin API, console and other buckets included, answers <code>404</code>, so they stay inside the installation. Backups hold every evidence file; see <a href="/wake-dist/docs/run/backup">Back up and restore</a>.</p><h2 id="your-own-storage" tabindex="-1">Your own storage <a class="header-anchor" href="#your-own-storage" aria-label="Permalink to &quot;Your own storage&quot;">​</a></h2><p>A server you run yourself can use S3, Cloudflare R2 or MinIO, with the <code>EVIDENCE_S3_*</code> variables of the <a href="/wake-dist/docs/reference/environment#evidence-storage">server environment</a>:</p><ul><li>Create the bucket before the first upload; Wake does not create it.</li><li>Give the server a key limited to that bucket, never the storage&#39;s root key. It needs <code>PutObject</code>, <code>GetObject</code> and <code>DeleteObject</code> on it (a <code>HEAD</code> check needs <code>GetObject</code>, and rejected uploads are deleted).</li><li><code>EVIDENCE_S3_ENDPOINT</code> is the address agents and browsers reach, since presigned addresses point there. When the server reaches the storage another way, such as inside a private network, set <code>EVIDENCE_S3_INTERNAL_ENDPOINT</code> too.</li></ul><p>Without storage the server still starts, and uploads answer <code>evidence_storage_unavailable</code>.</p>',10)])])}const v=o(r,[["render",d]]);export{p as __pageData,v as default};
